CREATE TABLE IF NOT EXISTS turmas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR(255) NOT NULL, nome_disciplina VARCHAR(255) NOT NULL, semestre VARCHAR(255) NOT NULL, horario VARCHAR(255), capacidade_maxima INTEGER, teacher_id BIGINT);
CREATE TABLE IF NOT EXISTS disciplinas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255) NOT NULL, carga_horaria INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS horarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, dia_semana VARCHAR(255) NOT NULL, hora_inicio TIME NOT NULL, hora_fim TIME NOT NULL, turma_id BIGINT NOT NULL REFERENCES turmas(id), disciplina_id BIGINT NOT NULL REFERENCES disciplinas(id), professor_id BIGINT);
CREATE TABLE IF NOT EXISTS turma_alunos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, turma_id BIGINT NOT NULL, aluno_id BIGINT NOT NULL, UNIQUE(turma_id, aluno_id));
CREATE TABLE IF NOT EXISTS solicitacoes_matricula (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, aluno_id BIGINT NOT NULL, turma_id BIGINT NOT NULL, status VARCHAR(255) NOT NULL, UNIQUE(aluno_id,turma_id));
